-- evt:kalindra_4
RegisterEvent(259, nil, function()
    if not ((Xeen.stageOf("kalindra") >= 4)) then
        evt.SetFacetBit(18, FacetBits.Invisible, 0)
        evt.SetFacetBit(18, FacetBits.Untouchable, 0)
        evt.SetFacetBit(19, FacetBits.Invisible, 1)
        evt.SetFacetBit(19, FacetBits.Untouchable, 1)
        evt.SetMapVar("AmbientSound13", 1)
        return
    end
    evt.SetFacetBit(18, FacetBits.Invisible, 1)
    evt.SetFacetBit(18, FacetBits.Untouchable, 1)
    evt.SetFacetBit(19, FacetBits.Invisible, 0)
    evt.SetFacetBit(19, FacetBits.Untouchable, 0)
    evt.SetMapVar("AmbientSound13", 2)
end)

