-- evt:kalindra_phase
RegisterEvent(265, nil, function()
    local s = Xeen.stageOf("kalindra") if s ~= evt.GetMapVar("kalindra_stage_shown", 0) then evt.SetMapVar("kalindra_stage_shown", s) evt.PlaySoundName("xeen_phase_shift", -12800, -3072, 2550) end
end)

-- evt:sardaj_war
RegisterEvent(266, nil, function()
    if not (((((IsQBitSet(QBit(113242))) or (IsQBitSet(QBit(113244))))) and (not (IsAtLeast(MapVar(6), 1))))) then
        return
    end
    SetValue(MapVar(6), 1)
    evt.SetMonGroupBit(60, MonsterBits.Hostile, true)
end)
